40	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
41	     * otherwise 'PHONE'.
42	     */
43	    default String contactPreference(Owner owner) {
44	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
45	        return hasEmail ? "EMAIL" : "PHONE";
46	    }
47	
48	    /**
49	     * The canonical region derived from the owner's city using the fixed
50	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or
51	     * 'UNKNOWN' when the city is not in the table.
52	     */
53	    default String locality(Owner owner) {
54	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
55	    }
56	
57	    /**
58	     * The owner's numeric membership level, assigned on creation. It starts at 1, gains
59	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
60	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
61	     */
62	    default Integer membershipLevel(Owner owner) {
63	        int level = 1;
64	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
65	        if (hasEmail) {
66	            level++;
67	        }
68	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
69	        if (noNamesakes) {
70	            level++;
71	        }
72	        return Math.min(level, 3);
73	    }
74	
75	    /**
76	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
77	     * is the last two digits of the registrationDate year (e.g. 'SYD-SMI-0007-M26').
78	     */
79	    default String membershipNumber(Owner owner) {
80	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
81	            return null;
82	        }
83	        return String.format("%s-M%02d", owner.getCustomerCode(),
84	            owner.getRegistrationDate().getYear() % 100);
85	    }
86	
87	    /**
88	     * The upper-cased first letters of firstName and lastName, dot-separated with a
89	     * trailing dot, e.g. 'J.S.'.
90	     */
91	    default String initials(Owner owner) {
92	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
93	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
94	    }
95	
96	    /**
97	     * A stable identifier for the owner's household, derived deterministically from the
98	     * normalized last name and address (trimmed, lower-cased, whitespace collapsed).
99	     * Every owner sharing a household therefore receives the same identifier: the first
100	     * eight upper-case hex characters of the SHA-256 of '&lt;lastName&gt;|&lt;address&gt;'.
101	     */
102	    default String householdId(Owner owner) {
103	        String key = normalizeHouseholdKey(owner.getLastName()) + "|"
104	            + normalizeHouseholdKey(owner.getAddress());
105	        try {
106	            byte[] digest = MessageDigest.getInstance("SHA-256")
107	                .digest(key.getBytes(StandardCharsets.UTF_8));
108	            StringBuilder sb = new StringBuilder();
109	            for (int i = 0; i < 4; i++) {
110	                sb.append(String.format("%02X", digest[i]));
111	            }
112	            return sb.toString();
113	        }
114	        catch (java.security.NoSuchAlgorithmException e) {
115	            throw new IllegalStateException(e);
116	        }
117	    }
118	
119	    /**
120	     * The owner's derived identity key: the single value onto which all duplicate
121	     * detection is consolidated, formatted
122	     * '&lt;normalizedTelephone&gt;|&lt;email or empty&gt;|&lt;householdId&gt;'.
123	     * The telephone and email are the owner's stored (already normalized) values;
124	     * a {@code null} email contributes the empty string. Two owners are duplicates
125	     * only when their whole identity keys are equal.
126	     */
127	    default String identityKey(Owner owner) {
128	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
129	        String email = owner.getEmail() == null ? "" : owner.getEmail();
130	        return telephone + "|" + email + "|" + householdId(owner);
131	    }
