27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    /**
81	     * Required national-number length keyed by E.164 country calling code: a
82	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
83	     * (NANP) number carries 10. A number whose country code is listed here must have
84	     * exactly the mandated number of national digits.
85	     */
86	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
87	        Map.of("61", 9, "1", 10);
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Validate & normalize the optional email; reject the create when it is present but invalid.
136	        if (!normalizeEmail(ownerFieldsDto)) {
137	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
138	        }
139	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
140	        // abbreviations) and store the normalized form back on the DTO so it is what gets
141	        // persisted and compared. Reject the create when the address is blank once normalized.
142	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
143	        if (canonicalAddress.isBlank()) {
144	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
145	        }
146	        ownerFieldsDto.setAddress(canonicalAddress);
147	        // Reject the create when the owner's city is already at capacity, i.e. it already
148	        // contains 50 or more owners (compared case-insensitively).
149	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
153	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
154	        if (normalizedTelephone == null) {
155	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
156	        }
157	        ownerFieldsDto.setTelephone(normalizedTelephone);
158	        // Consolidated duplicate detection. All former separate telephone, email and household
159	        // duplicate checks are now expressed through the single derived identity key
160	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
161	        // A create is rejected only when the new owner's identity collides with an existing owner's.
162	        // Because the telephone is part of the identity, two members of the same household with
163	        // different telephones no longer collide and are both allowed; only owners that share the
164	        // same normalized telephone and email are treated as the same identity.
165	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
166	        String contactIdentity = identityContact(candidate);
167	        boolean identityInUse = this.clinicService.findAllOwners().stream()
168	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
169	        if (identityInUse) {
170	            return new ResponseEntity<>(HttpStatus.CONFLICT);
171	        }
172	        // Determine the effective registration date — the value supplied on the request, or the
173	        // server's current date when none was supplied — and roll it forward to the next business
174	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
175	        // registration date (membership-number year segment, per-day create-limit) uses this
176	        // adjusted date.
177	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
178	        if (registrationDate == null) {
179	            registrationDate = LocalDate.now();
180	        }
181	        registrationDate = toBusinessDay(registrationDate);
182	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
183	        // owners have already been registered on this (adjusted) business day.
184	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
185	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = candidate;
189	        owner.setRegistrationDate(registrationDate);
190	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
191	        // letters of the city, the upper-cased first three letters of the last name, and a
192	        // per-city 4-digit sequence one greater than the number of owners already in that city.
193	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
194	        // Record how many existing owners already share this owner's first and last name
195	        // (compared case-insensitively) at the moment before this owner is created.
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
198	        // registered on this (adjusted) business day before this owner is created.
199	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
200	        // Record the size of this owner's household after this create: the number of existing
201	        // owners sharing the same household (matching last name and address) plus this owner.
202	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
203	        this.clinicService.saveOwner(owner);
204	        // Emit an audit line recording the new owner's id, customer code, registration date
205	        // and membership level.
206	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
208	            ownerMapper.membershipLevel(owner));
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        headers.setLocation(UriComponentsBuilder.newInstance()
211	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
212	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
213	    }
214	
215	    /**
216	     * Validate and normalize the optional owner email in place.
217	     *
218	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
219	     * When present it must be a syntactically valid address; a valid address is
220	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
221	     * present but syntactically invalid, so the caller can reject with 400.
222	     */
223	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
224	        String email = ownerFieldsDto.getEmail();
225	        if (email == null || email.isBlank()) {
226	            ownerFieldsDto.setEmail(null);
227	            return true;
228	        }
229	        String normalized = email.trim().toLowerCase(Locale.ROOT);
230	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
231	            return false;
232	        }
233	        ownerFieldsDto.setEmail(normalized);
234	        return true;
235	    }
236	
237	    /**
238	     * Normalize an owner address: trim, collapse each run of whitespace to a single
239	     * space, upper-case, and expand common street-type abbreviations
240	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
241	     * A {@code null} value normalizes to the empty string.
242	     */
243	    private static String normalizeAddress(String value) {
244	        if (value == null) {
245	            return "";
246	        }
247	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
248	        if (collapsed.isEmpty()) {
249	            return "";
250	        }
251	        String[] tokens = collapsed.split(" ");
252	        StringBuilder sb = new StringBuilder(collapsed.length());
253	        for (int i = 0; i < tokens.length; i++) {
254	            if (i > 0) {
255	                sb.append(' ');
256	            }
257	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
258	        }
259	        return sb.toString();
260	    }
261	
262	    /**
263	     * The contact portion of an owner's derived identity key: its normalized telephone and
264	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
265	     * without the household segment. Two owners share an identity when this value is equal;
266	     * because the telephone is part of it, members of one household with different telephones
267	     * do not collide. A {@code null} email contributes the empty string.
268	     */
269	    private static String identityContact(Owner owner) {
270	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
271	        String email = owner.getEmail() == null ? "" : owner.getEmail();
272	        return telephone + "|" + email;
273	    }
274	
275	    /**
276	     * Normalize an owner household field (last name or address) for duplicate detection:
277	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
278	     * A {@code null} value normalizes to the empty string.
279	     */
280	    private static String normalizeHouseholdKey(String value) {
281	        if (value == null) {
282	            return "";
283	        }
284	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
285	    }
286	
287	    /**
288	     * Normalize a telephone number to E.164 form.
289	     *
290	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
291	     * explicit leading {@code '+'} and country code it is kept; otherwise the
292	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
293	     * dropped from the national digits. The result must contain 8 to 15 digits
294	     * after the {@code '+'}, and — for a recognised country calling code — exactly
295	     * the national-number length that code mandates ({@code '+61'} => 9 national
296	     * digits, {@code '+1'} => 10).
297	     *
298	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
299	     *         the input is absent or cannot form a valid E.164 number.
300	     */
301	    private static String toE164(String raw) {
302	        if (raw == null) {
303	            return null;
304	        }
305	        String trimmed = raw.trim();
306	        boolean hasCountryCode = trimmed.startsWith("+");
307	        // Strip spaces, dashes and brackets.
308	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
309	        String digits;
310	        if (hasCountryCode) {
311	            // Keep the explicit country code; drop the leading '+' for validation.
312	            digits = stripped.substring(1);
313	        } else {
314	            // No country code: assume '+61' and drop a single leading '0'.
315	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
316	            digits = "61" + national;
317	        }
318	        if (!digits.matches("\\d{8,15}")) {
319	            return null;
320	        }
321	        // For a recognised country calling code, enforce the exact national-number length it
322	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
323	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
324	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
325	                .sorted((a, b) -> b.length() - a.length()).toList()) {
326	            if (digits.startsWith(countryCode)) {
327	                int nationalLength = digits.length() - countryCode.length();
328	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
329	                    return null;
330	                }
331	                break;
332	            }
333	        }
334	        return "+" + digits;
335	    }
336	
337	    /**
338	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
339	     *
340	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
341	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
342	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
343	     * equal to one more than the number of owners already in that city
344	     * (e.g. {@code 'SYD-SMI-0007'}).
345	     */
346	    /**
347	     * Count the existing owners whose first and last name match the given names,
348	     * compared case-insensitively. Used to record an owner's namesake count at the
349	     * moment before it is created.
350	     */
351	    private int countNamesakes(String firstName, String lastName) {
352	        return (int) this.clinicService.findAllOwners().stream()
353	            .filter(existing -> existing.getFirstName() != null
354	                && existing.getFirstName().equalsIgnoreCase(firstName)
355	                && existing.getLastName() != null
356	                && existing.getLastName().equalsIgnoreCase(lastName))
357	            .count();
358	    }
359	
360	    /**
361	     * Count the existing owners in the same household as the given last name and address
362	     * (compared after household-key normalization). Used, together with the owner being
363	     * created, to derive the household size recorded on the owner.
364	     */
365	    private int countHouseholdMembers(String lastName, String address) {
366	        String normalizedLastName = normalizeHouseholdKey(lastName);
367	        String normalizedAddress = normalizeHouseholdKey(address);
368	        return (int) this.clinicService.findAllOwners().stream()
369	            .filter(existing ->
370	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
371	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
372	            .count();
373	    }
374	
375	    private String nextCustomerCode(String city, String lastName) {
376	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
377	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
378	        int sequence = countOwnersInCity(city) + 1;
379	        return String.format("%s-%s-%04d", city3, last3, sequence);
380	    }
381	
382	    /**
383	     * Count the existing owners located in the given city, compared case-insensitively.
384	     * Used to derive the per-city 4-digit sequence in the customer code.
385	     */
386	    private int countOwnersInCity(String city) {
387	        return (int) this.clinicService.findAllOwners().stream()
388	            .filter(existing -> existing.getCity() != null
389	                && existing.getCity().equalsIgnoreCase(city))
390	            .count();
391	    }
392	
393	    /**
394	     * Count the existing owners whose registration date is the given (adjusted business) date.
395	     * Used to enforce the per-day sign-up limit.
396	     */
397	    private int countOwnersRegisteredOn(LocalDate date) {
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> date.equals(existing.getRegistrationDate()))
400	            .count();
401	    }
402	
403	    /**
404	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
405	     * the following Monday; a weekday is returned unchanged.
406	     */
407	    private static LocalDate toBusinessDay(LocalDate date) {
408	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
409	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
410	            date = date.plusDays(1);
411	        }
412	        return date;
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
418	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
419	        if (currentOwner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        if (!normalizeEmail(ownerFieldsDto)) {
423	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
424	        }
425	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
426	        if (normalizedTelephone == null) {
427	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
428	        }
429	        currentOwner.setAddress(ownerFieldsDto.getAddress());
430	        currentOwner.setCity(ownerFieldsDto.getCity());
431	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
432	        currentOwner.setLastName(ownerFieldsDto.getLastName());
433	        currentOwner.setTelephone(normalizedTelephone);
434	        currentOwner.setEmail(ownerFieldsDto.getEmail());
435	        this.clinicService.saveOwner(currentOwner);
436	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Transactional
441	    @Override
442	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
443	        Owner owner = this.clinicService.findOwnerById(ownerId);
444	        if (owner == null) {
445	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
446	        }
447	        this.clinicService.deleteOwner(owner);
448	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
454	        Owner owner = this.clinicService.findOwnerById(ownerId);
455	        if (owner == null) {
456	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
457	        }
458	        HttpHeaders headers = new HttpHeaders();
459	        Pet pet = petMapper.toPet(petFieldsDto);
460	        owner.setId(ownerId);
461	        pet.setOwner(owner);
462	        pet.getType().setName(null);
463	        this.clinicService.savePet(pet);
464	        PetDto petDto = petMapper.toPetDto(pet);
465	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
466	            .buildAndExpand(pet.getId()).toUri());
467	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
468	    }
469	
470	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
471	    @Override
472	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
473	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
474	        if (currentOwner != null) {
475	            Pet currentPet = this.clinicService.findPetById(petId);
476	            if (currentPet != null) {
477	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
478	                currentPet.setName(petFieldsDto.getName());
479	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
480	                this.clinicService.savePet(currentPet);
481	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
482	            }
483	        }
484	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
485	    }
486	
487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Override
489	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
490	        HttpHeaders headers = new HttpHeaders();
491	        Visit visit = visitMapper.toVisit(visitFieldsDto);
492	        Pet pet = new Pet();
493	        pet.setId(petId);
494	        visit.setPet(pet);
495	        this.clinicService.saveVisit(visit);
496	        VisitDto visitDto = visitMapper.toVisitDto(visit);
497	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
498	            .buildAndExpand(visit.getId()).toUri());
499	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
500	    }
501	
502	
503	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
504	    @Override
505	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
506	        Owner owner = this.clinicService.findOwnerById(ownerId);
507	        if (owner != null) {
508	            Pet pet = owner.getPet(petId);
509	            if (pet != null) {
510	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
511	            }
512	        }
513	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
514	    }
515	}
